script:
function generateColor(box) {
	if (box.miss_update === true && box.lack_update === false) {
		return "#ef4444"; // red-500
	}
	if (box.lack_update === true && box.miss_update === false) {
		return "#f97316"; // orange-500
	}
	return "#22c55e"; // green-500
}

function escapeHtml(unsafe) {
    if (unsafe === undefined || unsafe === null) return "";
    return String(unsafe)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
}

let allOutdatedBoxData = {};

frappe.after_ajax(() => {
	const filterEl = root_element.querySelector("#ob-box-type-filter");
	if (filterEl) {
		filterEl.addEventListener("change", () => {
			renderBoxes(allOutdatedBoxData, filterEl.value);
		});
	}
	renderOutdatedBoxes();
});

function renderOutdatedBoxes() {
	frappe.call({
		method: "service_warehouse.service_warehouse.dashboard_chart_source.service_packets.get_host_server_boxes_info",
		args: {},
		callback: function (response) {
			const data = response.message;
			allOutdatedBoxData = data.tenants;
			const filterEl = root_element.querySelector("#ob-box-type-filter");
			const filterValue = filterEl ? filterEl.value : "all";
			renderBoxes(allOutdatedBoxData, filterValue);
		},
	});
}

function renderBoxes(tenants, filterValue) {
	const container = root_element.querySelector("#outdated-boxes");
	if (!container) return;
	container.innerHTML = "";
	let hasContent = false;

	Object.entries(tenants).forEach(([tenant, boxes]) => {
		const filteredBoxes = filterValue === "all"
			? boxes
			: boxes.filter(b => b.box_type === filterValue);

		if (filteredBoxes.length === 0) return;
		hasContent = true;

		const ok    = filteredBoxes.filter(b => !b.miss_update && !b.lack_update).length;
		const lacks = filteredBoxes.filter(b => b.lack_update && !b.miss_update).length;
		const miss  = filteredBoxes.filter(b => b.miss_update && !b.lack_update).length;

		const tenantDiv = document.createElement("div");
		tenantDiv.className = "tenant-card";

		tenantDiv.innerHTML = `
			<div class="tenant-header">
				<div class="tenant-title">${tenant}</div>
				<div class="ob-count-wrap">
					<div class="tenant-count">${filteredBoxes.length} boxes</div>
					<div class="ob-status-popup">
						<div class="ob-status-row"><span class="ob-dot" style="background:#22c55e;"></span> Up to date <strong>${ok}</strong></div>
						<div class="ob-status-row"><span class="ob-dot" style="background:#f97316;"></span> Lacks update <strong>${lacks}</strong></div>
						<div class="ob-status-row"><span class="ob-dot" style="background:#ef4444;"></span> Not updated <strong>${miss}</strong></div>
					</div>
				</div>
			</div>
			<div class="packet-grid"></div>
		`;

		const grid = tenantDiv.querySelector(".packet-grid");

		filteredBoxes.forEach((box) => {
			const div = document.createElement("div");
			div.className = "packet-item";

			const color = generateColor(box);
			div.style.setProperty("--clr", color);

			const url = `/app/server-box/${encodeURIComponent(box.name)}`;

			const versions = Array.isArray(box.service_packet_versions) ? box.service_packet_versions : [];
			const versionsHtml = versions.length
				? `<ul>${versions.map(v => `<li><a href="/app/service-packet-version/${escapeHtml(v.service_packet_version || v)}">${escapeHtml(v.service_packet_version || v)}</a></li>`).join('')}</ul>`
				: '';

			const boxTypeLabel = escapeHtml(box.box_type || "");
			const boxTypeBadgeClass = box.box_type === "Client Box"
				? "badge-client"
				: box.box_type === "Service Box"
				? "badge-service"
				: "";

			div.innerHTML = `
				${boxTypeLabel ? `<span class="box-type-badge ${boxTypeBadgeClass}">${boxTypeLabel}</span>` : ""}
				<a href="${url}">
					<div class="packet-service">${box.box_name}</div>
				</a>
				<div class="packet-provider">
					Current: ${box.server_box_version}
				</div>
				<div class="packet-versions">${versionsHtml}</div>
			`;

			grid.appendChild(div);
		});

		container.appendChild(tenantDiv);
	});

	if (!hasContent) {
		container.innerHTML = `<div class="sp-empty">No boxes found for selected type.</div>`;
	}
}

