  border-bottom: 1px solid #f1f5f9;
}

.tenant-title {
  font-size: 20px;
  font-weight: 700;
  color: #1f2937;
}

.packet-versions {
    margin-top: 6px;
    padding: 0;
    font-size: 12px;
    color: #555;
    max-height: 140px;           /* Çok uzun listelerde taşma olmasın */
    overflow-y: auto;
    border-left: 3px solid var(--clr);   /* Kutunun rengini yansıt */
    padding-left: 8px;
}

.packet-versions ul {
    list-style: none;
    margin: 0;
    padding: 0;
}

.packet-versions li {
    padding: 3px 0;
    border-bottom: 1px dashed rgba(0,0,0,0.1);
    font-size: 12px;
    white-space: nowrap;          /* Taşma engelle */
    overflow: hidden;
    text-overflow: ellipsis;
}

.packet-versions li:last-child {
    border-bottom: none;
}

/* Scrollbar tasarımı */
.packet-versions::-webkit-scrollbar {
    width: 4px;
}

.packet-versions::-webkit-scrollbar-thumb {
    background: rgba(0,0,0,0.2);
    border-radius: 4px;
}

.packet-versions::-webkit-scrollbar-track {
    background: transparent;
}


.tenant-count {
  font-size: 12px;
  padding: 3px 8px;
  background: #f3f4f6;
  border-radius: 999px;
}

/* Grid */
.packet-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 12px;
}

/* Box item */
.packet-item {
  --clr: #22c55e; /* default green */
  border-left: 8px solid var(--clr);
  background: #fafafa;
  border: 1px solid var(--sp-border);
  padding: 14px;
  border-radius: 10px;
  transition: transform .15s, box-shadow .15s;
}
.packet-item:hover {
  transform: translateY(-2px);
  box-shadow: var(--sp-shadow-hover);
}

/* Text colors */
.packet-item .packet-service,
.packet-item .packet-provider {
  color: var(--clr);
}

.packet-provider {
  font-size: 12px;
  font-weight: 600;
}
.packet-service {
  font-size: 15px;
  font-weight: 700;
  margin-top: 5px;
}

/* ── Toolbar ──────────────────────────────── */
.ob-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
  gap: 12px;
}

/* ── Legend / info icon ───────────────────── */
.ob-legend-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.ob-info-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: #e5e7eb;
  color: #374151;
  font-size: 15px;
  cursor: pointer;
  position: relative;
  font-style: normal;
  user-select: none;
  line-height: 1;
}

.ob-legend-popup {
  display: none;
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  padding: 10px 14px;
  box-shadow: 0 6px 20px rgba(0,0,0,0.12);
  white-space: nowrap;
  z-index: 200;
  min-width: 280px;
}

.ob-info-icon:hover .ob-legend-popup {
  display: block;
}

.ob-legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 0;
  font-size: 13px;
  color: #374151;
}

.ob-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

/* ── Box-type filter ──────────────────────── */
.ob-filter-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.ob-filter-label {
  font-size: 13px;
  font-weight: 600;
  color: #374151;
  white-space: nowrap;
  margin: 0;
}

.ob-filter-select {
  border: 1px solid #d1d5db;
  border-radius: 6px;
  padding: 5px 10px;
  font-size: 13px;
  background: #fff;
  color: #1f2937;
  cursor: pointer;
  outline: none;
}

.ob-filter-select:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 2px rgba(99,102,241,0.15);
}

/* ── Box-type badge ───────────────────────── */
.box-type-badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 999px;
  margin-bottom: 6px;
  letter-spacing: 0.3px;
}

.badge-client {
  background: #dbeafe;
  color: #1d4ed8;
}

.badge-service {
  background: #d1fae5;
  color: #065f46;
}

