                    div.innerHTML = `
                        <a href="${url}">
                            <div class="rs-packet-title">${row.service_packet}</div>
                        </a>
                        <div class="rs-packet-status">Status: ${row.status}</div>
                    `;

                    grid.appendChild(div);
                });

                container.appendChild(tenantDiv);
            });
        },
    });
}

