script:
let lastXDayFilterValue = 7;

// Status renklerine göre ayırma
function getStatusColor(status) {
    switch (status) {
        case "Submitted":
            return "#22c55e"; // green-500
        case "Draft":
            return "#fbbf24"; // yellow-400
        case "Cancelled":
            return "#ef4444"; // red-500
        default:
            return "#6b7280"; // gray-500
    }
}

function openLastXDaysFilter() {
    frappe.prompt(
        [
            {
                fieldname: "min_count",
                label: "Show Last X Day",
                fieldtype: "Int",
                default: lastXDayFilterValue,
            },
        ],
        (values) => {
            lastXDayFilterValue = values.min_count;
            renderRecentSubscriptions(); // reload with filter
        },
        "Filter Subscribed Packets",
        "Apply"
    );
}

frappe.after_ajax(() => {
    const btn = root_element.querySelector("#tsp-filter-btn");
    if (btn) {
        btn.addEventListener("click", openLastXDaysFilter);
    }
    renderRecentSubscriptions();
});

function renderRecentSubscriptions() {
    frappe.call({
        method: "service_warehouse.service_warehouse.dashboard_chart_source.service_packets.get_subscribed_packets_within_time_for_host",
        args: { days: lastXDayFilterValue },
        callback: function (response) {
            const tenants = response.message || {};
            console.log("recent subs:", tenants);

            const container = root_element.querySelector("#recent-subs-list");
            if (!container) return;

            container.innerHTML = "";

            if (Object.keys(tenants).length === 0) {
                container.innerHTML = `<div class="rs-empty">No subscriptions in the last ${lastXDayFilterValue} days 🎉</div>`;
                return;
            }

            Object.entries(tenants).forEach(([tenant, list]) => {
                const tenantDiv = document.createElement("div");
                tenantDiv.className = "rs-tenant";

                tenantDiv.innerHTML = `
                    <div class="rs-tenant-header">
                        <div class="rs-tenant-title">${tenant}</div>
                        <div class="rs-count">${list.length} subscriptions</div>
                    </div>
                    <div class="rs-grid"></div>
                `;

                const grid = tenantDiv.querySelector(".rs-grid");

                list.forEach((row) => {
                    const div = document.createElement("div");
                    div.className = "rs-item";

                    // Renk
                    const clr = getStatusColor(row.status);
                    div.style.setProperty("--clr", clr);

                    // Service Packet Doc URL
                    const url = `/app/service-packet/${encodeURIComponent(row.service_packet)}`;

                    div.innerHTML = `
                        <a href="${url}">
                            <div class="rs-packet-title">
                            Packet Name: ${row.service_packet}
                            </div>
                        </a>
                        <div class="rs-packet-status">Subscriber: ${row.tenant}</div>
                    `;

                    grid.appendChild(div);
                });

                container.appendChild(tenantDiv);
            });
        },
    });
}

