script:
(function () {
  const method = 'service_warehouse.pilot_marketplace.doctype.pilot_flight.pilot_flight.get_my_pilot_workspace_data';

  function esc(value) {
    return String(value || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function formatNumber(value) {
    return new Intl.NumberFormat().format(Number(value || 0));
  }

  function formatHours(value) {
    const amount = Number(value || 0);
    return `${amount.toFixed(amount % 1 === 0 ? 0 : 1)} h`;
  }

  function formatDate(value) {
    if (!value) return 'No flight date yet';
    const parsed = new Date(value);
    if (Number.isNaN(parsed.getTime())) return esc(value);
    return parsed.toLocaleDateString();
  }

  function renderEmpty(message) {
    const stats = root_element.querySelector('#pilot-snapshot-stats');
    const tenants = root_element.querySelector('#pilot-tenant-breakdown');
    const flights = root_element.querySelector('#pilot-recent-flights');
    if (stats) stats.innerHTML = `<div class='pilot-block-empty'>${esc(message)}</div>`;
    if (tenants) tenants.innerHTML = `<div class='pilot-block-empty'>${esc(message)}</div>`;
    if (flights) flights.innerHTML = `<div class='pilot-block-empty'>${esc(message)}</div>`;
  }

  function render(data) {
    const profile = data.profile || null;
    if (!profile) {
      renderEmpty(data.message || 'Pilot profile not found.');
      return;
    }

    const stats = data.stats || {};
    const tenantBreakdown = data.tenant_breakdown || [];
    const recentFlights = data.recent_flights || [];

    const title = root_element.querySelector('#pilot-snapshot-title');
    const subtitle = root_element.querySelector('#pilot-snapshot-subtitle');
    const profileLink = root_element.querySelector('#pilot-profile-link');
    const flightsLink = root_element.querySelector('#pilot-flights-link');
    const statsWrap = root_element.querySelector('#pilot-snapshot-stats');
    const tenantWrap = root_element.querySelector('#pilot-tenant-breakdown');
    const flightWrap = root_element.querySelector('#pilot-recent-flights');
    const tenantCount = root_element.querySelector('#pilot-tenant-count');
    const flightCount = root_element.querySelector('#pilot-flight-count');

    if (title) title.textContent = profile.full_name || profile.pilot_id || 'Pilot Profile';
    if (subtitle) subtitle.textContent = `${profile.status || 'Pending'} pilot profile · ${profile.time_zone || 'No time zone'}`;
    if (profileLink) profileLink.href = profile.url || '/app/pilot-profile';
    if (flightsLink) flightsLink.href = profile.flights_url || '/app/pilot-flight';
    if (tenantCount) tenantCount.textContent = `${formatNumber(stats.tenant_count)} tenants`;
    if (flightCount) flightCount.textContent = `${formatNumber(stats.total_flights)} flights`;

    if (statsWrap) {
      statsWrap.innerHTML = `
        <article class='pilot-stat-card'>
          <span class='pilot-stat-label'>Total Flights</span>
          <strong class='pilot-stat-value'>${formatNumber(stats.total_flights)}</strong>
          <span class='pilot-stat-note'>All imported pilot flights</span>
        </article>
        <article class='pilot-stat-card'>
          <span class='pilot-stat-label'>Logged Hours</span>
          <strong class='pilot-stat-value'>${formatHours(stats.total_flight_hours)}</strong>
          <span class='pilot-stat-note'>Combined across every tenant</span>
        </article>
        <article class='pilot-stat-card'>
          <span class='pilot-stat-label'>Mapped Locations</span>
          <strong class='pilot-stat-value'>${formatNumber(stats.mapped_location_count)}</strong>
          <span class='pilot-stat-note'>Flights with valid geolocation</span>
        </article>
        <article class='pilot-stat-card'>
          <span class='pilot-stat-label'>Primary Aircraft</span>
          <strong class='pilot-stat-value'>${esc(stats.primary_aircraft || 'Not available')}</strong>
          <span class='pilot-stat-note'>Latest flight ${esc(formatDate(stats.latest_flight_date))}</span>
        </article>
      `;
    }

    if (tenantWrap) {
      if (!tenantBreakdown.length) {
        tenantWrap.innerHTML = "<div class='pilot-block-empty'>No tenant flight data yet.</div>";
      } else {
        tenantWrap.innerHTML = tenantBreakdown.map((row) => `
          <div class='pilot-tenant-row'>
            <div class='pilot-tenant-meta'>
              <strong>${esc(row.tenant)}</strong>
              <span>${formatNumber(row.flight_count)} flights · ${formatHours(row.flight_hours)}</span>
            </div>
            <div class='pilot-tenant-bar'>
              <span style='width:${Math.max(8, Number(row.share || 0))}%'></span>
            </div>
          </div>
        `).join('');
      }
    }

    if (flightWrap) {
      if (!recentFlights.length) {
        flightWrap.innerHTML = "<div class='pilot-block-empty'>No flights have been imported yet.</div>";
      } else {
        flightWrap.innerHTML = recentFlights.map((flight) => `
          <a class='pilot-flight-row' href='${esc(flight.url)}'>
            <div>
              <strong>${esc(flight.aircraft_name)}</strong>
              <span>${esc(flight.tenant)}</span>
            </div>
            <div class='pilot-flight-row__meta'>
              <strong>${formatHours(flight.flight_hours)}</strong>
              <span>${esc(formatDate(flight.flight_date))}</span>
            </div>
          </a>
        `).join('');
      }
    }
  }

  frappe.after_ajax(() => {
    frappe.call({
      method: method,
      callback: function (response) {
        render(response.message || {});
      },
      error: function () {
        renderEmpty('Pilot summary could not be loaded.');
      }
    });
  });
})();

