script:
(function () {
  const method = 'service_warehouse.pilot_marketplace.doctype.pilot_flight.pilot_flight.get_my_pilot_workspace_data';

  function esc(value) {
    return String(value || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function formatDate(value) {
    if (!value) return 'Date not available';
    const parsed = new Date(value);
    if (Number.isNaN(parsed.getTime())) return esc(value);
    return parsed.toLocaleDateString();
  }

  function colorForTenant(value) {
    let hash = 0;
    String(value || 'tenant').split('').forEach((char) => {
      hash = char.charCodeAt(0) + ((hash << 5) - hash);
    });
    const hue = Math.abs(hash) % 360;
    return `hsl(${hue}, 78%, 46%)`;
  }

  function setEmpty(message) {
    const mapElement = root_element.querySelector('#pilot-flight-atlas-map');
    const emptyElement = root_element.querySelector('#pilot-flight-atlas-empty');
    const summary = root_element.querySelector('#pilot-atlas-summary');
    if (mapElement) mapElement.style.display = 'none';
    if (emptyElement) {
      emptyElement.hidden = false;
      emptyElement.textContent = message;
    }
    if (summary) summary.textContent = message;
  }

  function renderMap(data) {
    const points = data.map_points || [];
    const stats = data.stats || {};
    const mapElement = root_element.querySelector('#pilot-flight-atlas-map');
    const emptyElement = root_element.querySelector('#pilot-flight-atlas-empty');
    const summary = root_element.querySelector('#pilot-atlas-summary');

    if (summary) {
      summary.textContent = `${points.length} mapped points across ${stats.tenant_count || 0} tenants`;
    }

    if (!window.L) {
      setEmpty('Leaflet could not be loaded in Desk.');
      return;
    }

    if (!points.length || !mapElement) {
      setEmpty('No mapped flight locations yet.');
      return;
    }

    if (emptyElement) emptyElement.hidden = true;
    mapElement.style.display = 'block';

    const map = L.map(mapElement);
    const satellite = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
      attribution: 'Tiles © Esri'
    });
    const terrain = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/NatGeo_World_Map/MapServer/tile/{z}/{y}/{x}', {
      attribution: 'Tiles © Esri, National Geographic',
      maxZoom: 16
    });
    const osm = L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '© OpenStreetMap'
    });

    satellite.addTo(map);
    L.control.layers({ Satellite: satellite, Terrain: terrain, OpenStreetMap: osm }).addTo(map);

    const bounds = [];
    points.forEach((point) => {
      const color = colorForTenant(point.tenant);
      const marker = L.circleMarker([point.lat, point.lng], {
        radius: 8,
        color: '#ffffff',
        weight: 2,
        fillColor: color,
        fillOpacity: 0.88,
      }).bindPopup(`
        <div class='pilot-map-popup'>
          <strong>${esc(point.aircraft_name || 'Unknown Aircraft')}</strong><br>
          <span>${esc(point.tenant || 'Unknown Tenant')}</span><br>
          <span>${esc(formatDate(point.flight_date))}</span><br>
          <a href='/app/pilot-flight/${encodeURIComponent(point.name)}'>Open flight</a>
        </div>
      `);

      marker.addTo(map);
      bounds.push([point.lat, point.lng]);
    });

    if (bounds.length) {
      map.fitBounds(bounds, { padding: [24, 24] });
    } else {
      map.setView([20, 0], 2);
    }
  }

  frappe.after_ajax(() => {
    frappe.call({
      method: method,
      callback: function (response) {
        renderMap(response.message || {});
      },
      error: function () {
        setEmpty('Map data could not be loaded.');
      }
    });
  });
})();

