script:
(function () {
  const method = 'service_warehouse.pilot_marketplace.doctype.pilot_flight.pilot_flight.get_my_pilot_workspace_data';

  function esc(value) {
    return String(value || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function formatHours(value) {
    const amount = Number(value || 0);
    return `${amount.toFixed(amount % 1 === 0 ? 0 : 1)} h`;
  }

  function render(data) {
    const rows = (data.tenant_aircraft_breakdown || []).map((row) => ({
      tenant: row.tenant,
      total_hours: Number(row.total_hours || 0)
    }));
    const chart = root_element.querySelector('#pilot-hours-chart');
    const summary = root_element.querySelector('#pilot-hours-summary');

    if (!chart) return;

    if (!rows.length) {
      chart.innerHTML = "<div class='pilot-hours-empty'>No flight-hour data is available yet.</div>";
      if (summary) summary.textContent = 'No chart data';
      return;
    }

    const maxTenantHours = Math.max(...rows.map((row) => row.total_hours), 1);
    const axisSteps = [1, 0.75, 0.5, 0.25, 0];
    const topGapPercent = 12;
    const maxBarPercent = 100 - topGapPercent;

    const axisLabels = axisSteps.map((step) => {
      const value = maxTenantHours * step;
      return `
        <span class='pilot-hours-axis-label' style='bottom: calc(${step * 100}% - 8px)'>${formatHours(value)}</span>
      `;
    }).join('');

    const gridLines = axisSteps.map((step) => `
      <span class='pilot-hours-grid-line' style='bottom:${step * 100}%'></span>
    `).join('');

    const bars = rows.map((tenantRow) => {
      const barHeight = tenantRow.total_hours > 0
        ? Math.max((tenantRow.total_hours / maxTenantHours) * maxBarPercent, 3)
        : 0;
      return `
        <div class='pilot-hours-bar-item'>
          <div class='pilot-hours-bar-zone' style='--bar-height:${barHeight}%'>
            <span class='pilot-hours-bar-total'>${formatHours(tenantRow.total_hours)}</span>
            <span class='pilot-hours-bar'></span>
          </div>
          <div class='pilot-hours-x-label'>${esc(tenantRow.tenant)}</div>
        </div>
      `;
    }).join('');

    if (summary) summary.textContent = `${rows.length} tenants compared`;

    chart.innerHTML = `
      <div class='pilot-hours-board'>
        <div class='pilot-hours-chart-shell'>
          <div class='pilot-hours-axis'>${axisLabels}</div>
          <div class='pilot-hours-plot'>
            <div class='pilot-hours-grid'>${gridLines}</div>
            <div class='pilot-hours-bars'>${bars}</div>
          </div>
        </div>
      </div>
    `;
  }

  frappe.after_ajax(() => {
    frappe.call({
      method: method,
      callback: function (response) {
        render(response.message || {});
      },
      error: function () {
        const chart = root_element.querySelector('#pilot-hours-chart');
        if (chart) {
          chart.innerHTML = "<div class='pilot-hours-empty'>Chart data could not be loaded.</div>";
        }
      }
    });
  });
})();

